def dedupe_stage_sequences(apps, schema_editor):
    """Renumber stage sequences per harvest so (harvest, sequence) is unique."""
    ProcessingStage = apps.get_model('crops', 'ProcessingStage')
    seen = {}
    for stage in ProcessingStage.objects.order_by('harvest_id', 'sequence', 'pk'):
        seen[stage.harvest_id] = seen.get(stage.harvest_id, 0) + 1
        if stage.sequence != seen[stage.harvest_id]:
            ProcessingStage.objects.filter(pk=stage.pk).update(sequence=seen[stage.harvest_id])


def backfill_payment_status(apps, schema_editor):
    """Credit sales are receivables; mark them unpaid by default."""
    Sale = apps.get_model('crops', 'Sale')
    Sale.objects.filter(payment_method='CREDIT').update(payment_status='UNPAID')


